import {openStudioDb,transact,requestResult} from '../../src/infrastructure/storage/database';
import {importAssets} from '../../src/features/assets/import-service';
import {f} from '../helpers/fixtures';
export function wave(frequency=220){const rate=8000,length=rate*12,buffer=new ArrayBuffer(44+length*2),v=new DataView(buffer);const text=(at:number,s:string)=>[...s].forEach((c,i)=>v.setUint8(at+i,c.charCodeAt(0)));text(0,'RIFF');v.setUint32(4,36+length*2,true);text(8,'WAVE');text(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);text(36,'data');v.setUint32(40,length*2,true);for(let i=0;i<length;i++)v.setInt16(44+i*2,Math.sin(i*2*Math.PI*frequency/rate)*3000,true);return new File([buffer],'声音'+frequency+'.wav',{type:'audio/wav'});}
export async function imageFile(){const canvas=document.createElement('canvas');canvas.width=32;canvas.height=16;canvas.getContext('2d')!.fillRect(0,0,32,16);const blob=await new Promise<Blob>(resolve=>canvas.toBlob(b=>resolve(b!),'image/png'));return new File([blob],'参考.png',{type:'image/png'});}
export async function seedAssetLibrary(){const db=await openStudioDb();try{await transact(db,db.tables.slice(),'readwrite',tx=>{for(const table of db.tables)tx.objectStore(table).clear();});const imported=await importAssets([wave(),wave(440),await imageFile()],undefined,{db});if(imported.failures.length)throw new Error('native media fixture import failed');const assets=imported.successes.map(s=>s.asset);await transact(db,['projects','graphs','references'],'readwrite',tx=>{tx.objectStore('projects').put(f.project({title:'素材项目'}));tx.objectStore('graphs').put(f.graph({nodes:[{id:'asset-node',title:'图片引用',type:'asset',x:40,y:40,locked:false,data:{kind:'asset',assetId:assets[2].id}}]}));tx.objectStore('references').put({id:'p1:'+assets[2].id,projectId:'p1',assetId:assets[2].id,revision:1});});return assets;}finally{db.close();}}
export async function storedAssets(){const db=await openStudioDb();try{return await transact(db,['assets','blobs','graphs','runs'],'readonly',async tx=>({assets:await requestResult(tx.objectStore('assets').getAll()),blobs:(await requestResult(tx.objectStore('blobs').getAll())).map(row=>({id:row.id,bytes:row.blob.size})),graph:await requestResult(tx.objectStore('graphs').get('p1')),runs:await requestResult(tx.objectStore('runs').getAll())}));}finally{db.close();}}
